const controller = require\('./controllers/journeyController'\);

// Mock req/res to test the flow
const testFlow = async \(\) => {
  let sessionId = null;

  const call = \(message, action, data\) => new Promise\(\(resolve\) => {
    const req = { body: { message, sessionId, action, data } };
    const res = {
      json: \(d\) => { sessionId = d.sessionId; resolve\(d\); },
      status: \(code\) => \({ json: \(d\) => resolve\({ ...d, statusCode: code }\) }\),
    };
    if \(action\) controller.handleAction\(req, res\);
    else controller.processMessage\(req, res\);
  }\);

  // Step 1: Select product via EMI intent
  let r = await call\('I want to buy the Samsung Galaxy S26 on EMI'\);
  console.log\('1. State:', r.journeyState, '| Text:', r.text.slice\(0, 60\)\);

  // Step 2: Provide name
  r = await call\('My name is Prakhar'\);
  console.log\('2. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);

  // Step 3: Provide phone
  r = await call\('9876543210'\);
  console.log\('3. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);

  // Step 4: Provide employment
  r = await call\('I am salaried'\);
  console.log\('4. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);

  // Step 5: Provide salary \(should auto-transition to consent\)
  r = await call\('80k per month'\);
  console.log\('5. State:', r.journeyState, '| Text:', r.text.slice\(0, 120\)\);

  // Step 6: Give consent \(should auto-transition through checking_eligibility to showing_offers\)
  r = await call\('Yes I agree'\);
  console.log\('6. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);
  console.log\('   Cards:', r.richCards?.map\(c => c.type\).join\(', '\)\);

  // Step 7: Select offer via action
  r = await call\(null, 'offer_selected', { lenderId: 'fibe', lenderName: 'Fibe', tenure: 6 }\);
  console.log\('7. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);

  // Step 8: Aadhaar verified via action
  r = await call\(null, 'aadhaar_verified', { aadhaar: '123456789012' }\);
  console.log\('8. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);
  console.log\('   Cards:', r.richCards?.map\(c => c.type\).join\(', '\)\);

  // Step 9: Payment done
  r = await call\(null, 'payment_done', {}\);
  console.log\('9. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);

  // Step 10: KFS accepted
  r = await call\(null, 'kfs_accepted', {}\);
  console.log\('10. State:', r.journeyState, '| Text:', r.text.slice\(0, 80\)\);

  console.log\('\\nFull journey completed successfully!'\);
};

testFlow\(\).catch\(e => console.error\('FAILED:', e\)\);
